6"}, {"score": "50", "semester": "2025-26 Sem-II", "course_code": "Industrial Safety for Semiconductor Industry", "planned_classes": "31", "conducted_classes": "31"}], "products": [{"hod": "", "score": "10", "usage": "Used by Students & proposed for commercialization", "details": "C2S Facility and Silicon Forge Lab Setup at Department of Semiconductor Engineering at DYPIU", "director": ""}], "projects": [{"hod": "", "label": "", "score": "", "director": ""}], "research": [{"hod": "", "score": "", "degree": "", "thesis": "", "director": "", "student_name": ""}], "training": [{"hod": "", "score": "", "nature": "", "company": "", "director": "", "duration": ""}], "innovRows": [{"score": "2", "method": "Website", "details": "Website for Sharing Study Material"}, {"score": "2", "method": "Case study", "details": "On ISSI"}, {"score": "2", "method": "Activity", "details": "Role play on ISSI"}, {"score": "2", "method": "Paper Presentation", "details": "ISSI"}, {"score": "2", "method": "Workshop on Fire Extinguisher", "details": "Workshop mof SY conducted on fire extinguisher"}], "projects2": [{"hod": "", "role": "fabrication lab set up", "score": "15", "title": "fabrication and characterizatin of scaled mosfets: impact of gate length of device parameter", "agency": "DYPIU", "amount": "25000000", "sanction_date": "17/03/2024", "project_status": "completed"}], "proposals": [{"hod": "", "score": "10", "title": "Scalable Synthesis and Surface-Chemistry-Driven Oxidation Study of Ti3C2Tx  MXene", "agency": "DYPIU", "amount": "1000000", "director": "", "duration": "2 years"}], "courseFile": [{"hod": "", "score": "20", "title": "B. Tech Semiconductor Engineering, Semester 2", "course": "Computational Thinking with Python Programming", "details": "1.Available", "director": ""}, {"score": "20", "title": "B. Tech Semiconductor Engineering, Semester 4", "course": "Microcontroller & Applications", "details": "1.Available"}, {"score": "20", "title": "B. Tech Semiconductor Engineering, Semester 2", "course": "Digital Logic Design", "details": "1.Available"}, {"score": "20", "title": "B. Tech Semiconductor Engineering, Semester 4", "course": "Industrial Safety for Semiconductor Industry", "details": "1.Available"}], "innovScore": "10", "innovDetails": "Website, Case study, Activity, Paper Presentation, Workshop on Fire Extinguisher", "externalProjects": [{"hod": "", "role": "Co-PI", "score": "10", "title": "Fabrication of 2D Layered Sensors via Spray Pyrolysis and Integration into IoT Platforms for Remote Sensing and Automated Decision-Making", "agency": "ANRF Govt of India", "amount": "5910000", "sanction_date": "05/12/2025", "project_status": "revision Submitted"}, {"role": "PI", "score": "10", "title": "Optimization of Wire Bonding Parameters for Enhanced Reliability Using  Low-Cost Desktop Bonders", "agency": "DYPIU", "amount": "990000", "sanction_date": "22/05/2026", "project_status": "Ongoning"}, {"role": "CO-PI", "score": "10", "title": "From Student to Silicon Pro", "agency": "IEEE YP", "amount": "29000", "sanction_date": "25/08/2025", "project_status": "Completed"}], "internalProjects": [], "summaryOtherInfo": "Played a pivotal role in establishing the Semiconductor Fabrication Laboratory from inception over the past two years, contributing extensively to infrastructure development, planning, and execution. Actively contributed to the design and development of the Semiconductor Engineering curriculum aligned with current industry requirements and emerging technologies. Strengthened industry–academia collaboration through continuous engagement with organizations such as VLSI Society of India (VSI), IESA, MCCIA, and leading semiconductor industries.\\n\\nSuccessfully facilitated and coordinated the signing of Memoranda of Understanding (MoUs) with organizations including Kaynes Semicon Pvt. Ltd. and Sigasi, resulting in academic collaborations, industry interaction, and access to advanced EDA tools. Instrumental in securing a MeitY-sanctioned proposal under the C2S initiative, enabling free access to four industry-standard EDA software tools for academic and research purposes. Additionally, facilitated 100-user free EDA tool licenses through collaboration with Sigasi.\\n\\nActively worked towards enhancing student opportunities by arranging internships in reputed organizations such as Synopsys, Kaynes, YCM Institute, and SPPU. Organized and coordinated multiple Faculty Development Programs (FDPs), workshops, and technical sessions focused on semiconductor technologies and VLSI design to strengthen knowledge dissemination among students and faculty members.\\n\\nContinuously engaged in professional development by attending various FDPs, conferences, and technical events related to semiconductor technologies and emerging trends. Demonstrated leadership by guiding and coordinating the Semiconductor Engineering branch and fostering collaboration among faculty, students, and industry partners. Also contributed actively to university-level activities by anchoring several institutional events and serving as a member of the University Doctoral Committee.\\n\\nAdditional noteworthy contributions include achieving IEEE Senior Member status, reflecting professional excellence and significant contributions in the field of engineering and technology. Successfully initiated and established the IEEE Student Branch at the university level, encouraging active student participation and professional engagement through IEEE memberships and technical activities.\\n\\nFurther strengthened the semiconductor ecosystem within the institution by establishing the IEEE Electronics Packaging Society (EPS) Student Branch Chapter, which is currently the only IEEE EPS Student Branch Chapter in Maharashtra. This achievement has created a unique platform for students and faculty to engage with global advancements in semiconductor packaging, microelectronics, and emerging technologies through IEEE-sponsored activities, expert talks, workshops, and networking opportunities.\\n\\nConsistently motivated students to become active IEEE members and participate in technical events, competitions, conferences, and professional development activities. Demonstrated strong leadership and institutional commitment by fostering collaborations, building academic and industrial networks, and positioning the Semiconductor Engineering branch as an emerging center for semiconductor education and skill development.", "sectionSaveStatus": {"partA": true, "partB": true}, "sectionApplicability": {"society": "applicable", "projects": "notApplicable", "research": "notApplicable"}}, "status": "Pending Director Review", "totals": {"grandTotal": 446.609875, "partATotal": 163.109875, "partBTotal": 283.5, "effectiveGrandMax": 510, "effectivePartAMax": 165, "effectivePartBMax": 345}, "review_chain": ["director", "dean", "vc"], "academic_year": "2025-2026", "next_reviewer": "director", "workflow_status": "Pending Director Review", "submitter_profile": {"email": "priya.charles@dypiu.ac.in", "school": "SoEMR", "full_name": "Dr Mrs Priya Charles", "department": "Semiconductor Engineering", "experience": "", "designation": "Associate Professor & hod (Semiconductor Dept)", "employee_id": "", "qualification": "", "appraisal_role": "hod", "reportsToRegistrar": false, "teaching_experience": "", "reports_to_registrar": false}, "next_reviewer_role": "director"}	2026-05-25 14:03:27.105803+05:30	2026-08-25 23:49:25.410983+05:30
