    duration text,
    agency text,
    amount numeric,
    score numeric DEFAULT 0 NOT NULL,
    hod_score numeric,
    director_score numeric,
    dean_score numeric,
    vc_score numeric,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.research_proposals OWNER TO fac_user;

--
-- Name: mv_research_faculty_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_research_faculty_summary AS
 WITH journal_summary AS (
         SELECT lower(TRIM(BOTH FROM journal_publications.faculty_email)) AS faculty_email,
            count(*) AS total_journals,
            sum(COALESCE(journal_publications.score, (0)::numeric)) AS journal_score
           FROM public.journal_publications
          WHERE (NULLIF(TRIM(BOTH FROM journal_publications.title), ''::text) IS NOT NULL)
          GROUP BY (lower(TRIM(BOTH FROM journal_publications.faculty_email)))
        ), book_summary AS (
         SELECT lower(TRIM(BOTH FROM book_publications.faculty_email)) AS faculty_email,
            count(*) AS total_books,
            sum(COALESCE(book_publications.score, (0)::numeric)) AS book_score
           FROM public.book_publications
          WHERE (COALESCE(NULLIF(TRIM(BOTH FROM book_publications.title), ''::text), NULLIF(TRIM(BOTH FROM book_publications.book), ''::text)) IS NOT NULL)
          GROUP BY (lower(TRIM(BOTH FROM book_publications.faculty_email)))
        ), patent_summary AS (
         SELECT lower(TRIM(BOTH FROM patents.faculty_email)) AS faculty_email,
            count(*) AS total_patents,
            count(*) FILTER (WHERE (lower(COALESCE(patents.patent_status, ''::text)) ~~ '%grant%'::text)) AS patents_granted,
            sum(COALESCE(patents.score, (0)::numeric)) AS patent_score
           FROM public.patents
          WHERE (NULLIF(TRIM(BOTH FROM patents.title), ''::text) IS NOT NULL)
          GROUP BY (lower(TRIM(BOTH FROM patents.faculty_email)))
        ), project_summary AS (
         SELECT lower(TRIM(BOTH FROM deduped.faculty_email)) AS faculty_email,
            count(*) AS total_projects,
            sum(COALESCE(deduped.amount, (0)::numeric)) AS total_funding,
            count(*) FILTER (WHERE (deduped.external_project = true)) AS external_projects,
            sum(
                CASE
                    WHEN (deduped.external_project = true) THEN COALESCE(deduped.amount, (0)::numeric)
                    ELSE (0)::numeric
                END) AS external_funding,
            sum(COALESCE(deduped.score, (0)::numeric)) AS project_score
           FROM ( SELECT x.faculty_email,
                    x.amount,
                    x.score,
                    x.external_project
                   FROM ( SELECT up.source_table,
                            up.id,
                            up.faculty_email,
                            up.title,
                            up.amount,
                            up.score,
                            up.role,
                            up.project_status,
                            up.external_project,
                            up.project_key,
                            row_number() OVER (PARTITION BY up.project_key ORDER BY
                                CASE
                                    WHEN ((lower(COALESCE(up.role, ''::text)) ~~ '%principal%'::text) OR (lower(COALESCE(up.role, ''::text)) = 'pi'::text)) THEN 1
                                    ELSE 2
                                END, up.id) AS rn
                           FROM (( SELECT 'research_projects'::text AS source_table,
                                    research_projects.id,
                                    research_projects.faculty_email,
                                    research_projects.title,
                                    research_projects.amount,
                                    research_projects.score,
                                    research_projects.role,
                                    research_projects.project_status,
                                    false AS external_project,
                                    md5(((((lower(TRIM(BOTH FROM research_projects.title)) || '|'::text) || COALESCE((research_projects.amount)::text, '0'::text)) || '|'::text) || lower(TRIM(BOTH FROM COALESCE(research_projects.agency, ''::text))))) AS project_key
                                   FROM public.research_projects
                                  WHERE ((NULLIF(TRIM(BOTH FROM research_projects.title), ''::text) IS NOT NULL) AND ((COALESCE(TRIM(BOTH FROM research_projects.project_status), ''::text) = ''::text) OR (lower(COALESCE(research_projects.project_status, ''::text)) ~ similar_to_escape('%(sanction|ongoing|complete|closed|approved|active|grant)%'::text))) AND (lower(COALESCE(research_projects.project_status, ''::text)) <> ALL (ARRAY['proposed'::text, 'submitted'::text, 'rejected'::text, 'unknown'::text, 'draft'::text])))
                                UNION ALL
                                 SELECT 'external_research_projects'::text AS source_table,
                                    external_research_projects.id,
                                    external_research_projects.faculty_email,
                                    external_research_projects.title,
                                    external_research_projects.amount,
                                    (0)::numeric AS score,
                                    ''::text AS role,
                                    external_research_projects.project_status,
                                    true AS external_project,
                                    md5(((((lower(TRIM(BOTH FROM external_research_projects.title)) || '|'::text) || COALESCE((external_research_projects.amount)::text, '0'::text)) || '|'::text) || lower(TRIM(BOTH FROM COALESCE(external_research_projects.agency, ''::text))))) AS project_key
                                   FROM public.external_research_projects
                                  WHERE ((NULLIF(TRIM(BOTH FROM external_research_projects.title), ''::text) IS NOT NULL) AND ((COALESCE(TRIM(BOTH FROM external_research_projects.project_status), ''::text) = ''::text) OR (lower(COALESCE(external_research_projects.project_status, ''::text)) ~ similar_to_escape('%(sanction|ongoing|complete|closed|approved|active|grant)%'::text))) AND (lower(COALESCE(external_research_projects.project_status, ''::text)) <> ALL (ARRAY['proposed'::text, 'submitted'::text, 'rejected'::text, 'unknown'::text, 'draft'::text])))) up
                             JOIN public.faculty_profiles fp_1 ON ((lower(TRIM(BOTH FROM fp_1.email)) = lower(TRIM(BOTH FROM up.faculty_email)))))
                          WHERE (fp_1.is_active = true)) x
                  WHERE (x.rn = 1)) deduped
          GROUP BY (lower(TRIM(BOTH FROM deduped.faculty_email)))
        ), proposal_summary AS (
         SELECT lower(TRIM(BOTH FROM research_proposals.faculty_email)) AS faculty_email,
            count(*) AS total_proposals,
            sum(COALESCE(research_proposals.amount, (0)::numeric)) AS total_proposal_amount
           FROM public.research_proposals
          WHERE (NULLIF(TRIM(BOTH FROM research_proposals.title), ''::text) IS NOT NULL)
          GROUP BY (lower(TRIM(BOTH FROM research_proposals.faculty_email)))
        ), guidance_summary AS (
         SELECT lower(TRIM(BOTH FROM research_guidance.faculty_email)) AS faculty_email,
            count(*) AS total_scholars_guided
           FROM public.research_guidance
          GROUP BY (lower(TRIM(BOTH FROM research_guidance.faculty_email)))
        ), conference_summary AS (
         SELECT lower(TRIM(BOTH FROM conferences.faculty_email)) AS faculty_email,
            count(*) AS total_conferences
           FROM public.conferences
          WHERE (NULLIF(TRIM(BOTH FROM conferences.title), ''::text) IS NOT NULL)
          GROUP BY (lower(TRIM(BOTH FROM conferences.faculty_email)))
        ), award_summary AS (
         SELECT lower(TRIM(BOTH FROM awards.faculty_email)) AS faculty_email,
            count(*) AS total_awards
           FROM public.awards
          WHERE (NULLIF(TRIM(BOTH FROM awards.title), ''::text) IS NOT NULL)
          GROUP BY (lower(TRIM(BOTH FROM awards.faculty_email)))
        ), product_summary AS (
         SELECT lower(TRIM(BOTH FROM products_developed.faculty_email)) AS faculty_email,
            count(*) AS total_products
           FROM public.products_developed
          WHERE (NULLIF(TRIM(BOTH FROM products_developed.details), ''::text) IS NOT NULL)
          GROUP BY (lower(TRIM(BOTH FROM products_developed.faculty_email)))
        )
 SELECT lower(TRIM(BOTH FROM fp.email)) AS faculty_email,
    fp.employee_id,
    fp.full_name AS faculty_name,
    COALESCE(NULLIF(TRIM(BOTH FROM fp.school), ''::text), 'Unassigned'::text) AS school,
    COALESCE(NULLIF(TRIM(BOTH FROM fp.department), ''::text), (COALESCE(NULLIF(TRIM(BOTH FROM fp.school), ''::text), 'Unassigned'::text) || ' (No department mapped)'::text)) AS department,
    fp.designation,
    fp.is_active,
    COALESCE(js.total_journals, (0)::bigint) AS total_journals,
    COALESCE(bs.total_books, (0)::bigint) AS total_books,
    COALESCE(ps.total_patents, (0)::bigint) AS total_patents,
    COALESCE(ps.patents_granted, (0)::bigint) AS patents_granted,
    COALESCE(prs.total_projects, (0)::bigint) AS total_projects,
    COALESCE(prs.total_funding, (0)::numeric) AS total_funding,
    COALESCE(prs.external_projects, (0)::bigint) AS external_projects,
    COALESCE(prs.external_funding, (0)::numeric) AS external_funding,
    COALESCE(props.total_proposals, (0)::bigint) AS total_proposals,
    COALESCE(props.total_proposal_amount, (0)::numeric) AS total_proposal_amount,
    COALESCE(gs.total_scholars_guided, (0)::bigint) AS total_scholars_guided,
    COALESCE(cs.total_conferences, (0)::bigint) AS total_conferences,
    COALESCE(aws.total_awards, (0)::bigint) AS total_awards,
    COALESCE(prods.total_products, (0)::bigint) AS total_products,
    (((COALESCE(js.journal_score, (0)::numeric) + COALESCE(bs.book_score, (0)::numeric)) + COALESCE(ps.patent_score, (0)::numeric)) + COALESCE(prs.project_score, (0)::numeric)) AS total_research_score
   FROM (((((((((public.faculty_profiles fp
     LEFT JOIN journal_summary js ON ((lower(TRIM(BOTH FROM fp.email)) = js.faculty_email)))
     LEFT JOIN book_summary bs ON ((lower(TRIM(BOTH FROM fp.email)) = bs.faculty_email)))
     LEFT JOIN patent_summary ps ON ((lower(TRIM(BOTH FROM fp.email)) = ps.faculty_email)))
     LEFT JOIN project_summary prs ON ((lower(TRIM(BOTH FROM fp.email)) = prs.faculty_email)))
     LEFT JOIN proposal_summary props ON ((lower(TRIM(BOTH FROM fp.email)) = props.faculty_email)))
     LEFT JOIN guidance_summary gs ON ((lower(TRIM(BOTH FROM fp.email)) = gs.faculty_email)))
     LEFT JOIN conference_summary cs ON ((lower(TRIM(BOTH FROM fp.email)) = cs.faculty_email)))
     LEFT JOIN award_summary aws ON ((lower(TRIM(BOTH FROM fp.email)) = aws.faculty_email)))
     LEFT JOIN product_summary prods ON ((lower(TRIM(BOTH FROM fp.email)) = prods.faculty_email)))
  WHERE (fp.is_active = true)
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_research_faculty_summary OWNER TO postgres;

--
-- Name: mv_research_category_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_research_category_summary AS
 SELECT 'journal_publication'::text AS category,
    sum(mv_research_faculty_summary.total_journals) AS count,
    0.0 AS total_score,
    0.0 AS total_amount
   FROM public.mv_research_faculty_summary
UNION ALL
 SELECT 'book_publication'::text AS category,
    sum(mv_research_faculty_summary.total_books) AS count,
    0.0 AS total_score,
    0.0 AS total_amount
   FROM public.mv_research_faculty_summary
UNION ALL
 SELECT 'patent'::text AS category,
    sum(mv_research_faculty_summary.total_patents) AS count,
    0.0 AS total_score,
    0.0 AS total_amount
   FROM public.mv_research_faculty_summary
UNION ALL
 SELECT 'research_project'::text AS category,
    sum(mv_research_faculty_summary.total_projects) AS count,
    0.0 AS total_score,
    sum(mv_research_faculty_summary.total_funding) AS total_amount
   FROM public.mv_research_faculty_summary
UNION ALL
 SELECT 'research_proposal'::text AS category,
    sum(mv_research_faculty_summary.total_proposals) AS count,
    0.0 AS total_score,
    sum(mv_research_faculty_summary.total_proposal_amount) AS total_amount
   FROM public.mv_research_faculty_summary
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_research_category_summary OWNER TO postgres;

--
-- Name: mv_research_data_quality_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_research_data_quality_summary AS
 SELECT ( SELECT count(*) AS count
           FROM public.journal_publications
          WHERE (NULLIF(TRIM(BOTH FROM journal_publications.title), ''::text) IS NULL)) AS publications_with_missing_titles,
    ( SELECT count(*) AS count
           FROM public.book_publications
          WHERE (NULLIF(TRIM(BOTH FROM book_publications.isbn), ''::text) IS NULL)) AS books_with_missing_isbn,
    ( SELECT count(*) AS count
           FROM public.journal_publications
          WHERE (NULLIF(TRIM(BOTH FROM journal_publications.issn), ''::text) IS NULL)) AS journal_publications_with_missing_issn,
    ( SELECT count(*) AS count
           FROM public.journal_publications
          WHERE (NULLIF(TRIM(BOTH FROM journal_publications.indexing), ''::text) IS NULL)) AS publications_with_missing_indexing,
    ( SELECT count(*) AS count
           FROM public.patents
          WHERE (NULLIF(TRIM(BOTH FROM patents.patent_status), ''::text) IS NULL)) AS patents_with_missing_status,
    ( SELECT count(*) AS count
           FROM public.research_projects
          WHERE (research_projects.amount IS NULL)) AS projects_with_missing_funding_amount,
    ( SELECT count(*) AS count
           FROM (public.journal_publications jp
             LEFT JOIN public.faculty_profiles fp ON ((lower(TRIM(BOTH FROM fp.email)) = lower(TRIM(BOTH FROM jp.faculty_email)))))
          WHERE (fp.email IS NULL)) AS records_without_matching_faculty_email,
    ( SELECT count(*) AS count
           FROM public.faculty_profiles
          WHERE (NULLIF(TRIM(BOTH FROM faculty_profiles.department), ''::text) IS NULL)) AS blank_or_null_departments,
    ( SELECT count(*) AS count
           FROM public.faculty_profiles
          WHERE (NULLIF(TRIM(BOTH FROM faculty_profiles.academic_year), ''::text) IS NULL)) AS unknown_academic_years
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_research_data_quality_summary OWNER TO postgres;

--
-- Name: mv_research_department_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_research_department_summary AS
 SELECT school,
    department,
    count(faculty_email) AS total_active_faculty,
    count(
        CASE
            WHEN (total_journals > 0) THEN 1
            ELSE NULL::integer
        END) AS research_active_faculty,
    sum(total_journals) AS journal_publications,
    sum(total_books) AS book_publications,
    sum(total_patents) AS patents,
    sum(patents_granted) AS patents_granted,
    sum(total_projects) AS research_projects,
    sum(total_funding) AS total_project_funding,
    sum(total_proposals) AS research_proposals,
    sum(total_proposal_amount) AS total_proposal_amount,
    sum(total_scholars_guided) AS research_scholars_guided,
    sum(total_conferences) AS conferences,
    sum(total_awards) AS awards,
    sum(total_products) AS products_developed,
    sum(total_research_score) AS total_research_score
   FROM public.mv_research_faculty_summary
  GROUP BY school, department
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_research_department_summary OWNER TO postgres;

--
-- Name: mv_research_filter_options; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_research_filter_options AS
 SELECT ( SELECT array_agg(DISTINCT faculty_profiles.academic_year ORDER BY faculty_profiles.academic_year) AS array_agg
           FROM public.faculty_profiles
          WHERE (NULLIF(TRIM(BOTH FROM faculty_profiles.academic_year), ''::text) IS NOT NULL)) AS academic_years,
    ( SELECT array_agg(DISTINCT faculty_profiles.school ORDER BY faculty_profiles.school) AS array_agg
           FROM public.faculty_profiles
          WHERE (NULLIF(TRIM(BOTH FROM faculty_profiles.school), ''::text) IS NOT NULL)) AS schools,
    ( SELECT array_agg(DISTINCT faculty_profiles.department ORDER BY faculty_profiles.department) AS array_agg
           FROM public.faculty_profiles
          WHERE (NULLIF(TRIM(BOTH FROM faculty_profiles.department), ''::text) IS NOT NULL)) AS departments,
    ( SELECT array_agg(DISTINCT faculty_profiles.designation ORDER BY faculty_profiles.designation) AS array_agg
           FROM public.faculty_profiles
          WHERE (NULLIF(TRIM(BOTH FROM faculty_profiles.designation), ''::text) IS NOT NULL)) AS designations,
    ( SELECT array_agg(DISTINCT journal_publications.indexing ORDER BY journal_publications.indexing) AS array_agg
           FROM public.journal_publications
          WHERE (NULLIF(TRIM(BOTH FROM journal_publications.indexing), ''::text) IS NOT NULL)) AS indexing_options
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_research_filter_options OWNER TO postgres;

--
-- Name: mv_research_school_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_research_school_summary AS
 SELECT school,
    count(faculty_email) AS total_active_faculty,
    count(
        CASE
            WHEN (total_journals > 0) THEN 1
            ELSE NULL::integer
        END) AS faculty_who_published_papers,
    sum(total_journals) AS journal_publications,
    sum(total_books) AS book_publications,
    sum(total_patents) AS patents,
    sum(total_projects) AS research_projects,
    sum(total_funding) AS total_project_funding,
    sum(total_research_score) AS total_research_score,
    round((((count(
        CASE
            WHEN (total_journals > 0) THEN 1
            ELSE NULL::integer
        END))::numeric / (NULLIF(count(faculty_email), 0))::numeric) * (100)::numeric), 2) AS participation_rate
   FROM public.mv_research_faculty_summary
  GROUP BY school
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_research_school_summary OWNER TO postgres;

--
-- Name: mv_research_yearly_trend; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_research_yearly_trend AS
 WITH year_union AS (
         SELECT journal_publications.academic_year,
            'pub'::text AS type,
            (0)::numeric AS amount
           FROM public.journal_publications
          WHERE (NULLIF(TRIM(BOTH FROM journal_publications.title), ''::text) IS NOT NULL)
        UNION ALL
         SELECT book_publications.academic_year,
            'book'::text AS type,
            (0)::numeric AS amount
           FROM public.book_publications
          WHERE (COALESCE(NULLIF(TRIM(BOTH FROM book_publications.title), ''::text), NULLIF(TRIM(BOTH FROM book_publications.book), ''::text)) IS NOT NULL)
        UNION ALL
         SELECT patents.academic_year,
            'patent'::text AS type,
            (0)::numeric AS amount
           FROM public.patents
          WHERE (NULLIF(TRIM(BOTH FROM patents.title), ''::text) IS NOT NULL)
        UNION ALL
         SELECT deduped_projects.academic_year,
            'proj'::text AS type,
            COALESCE(deduped_projects.amount, (0)::numeric) AS amount
           FROM ( SELECT x.academic_year,
                    x.amount
                   FROM ( SELECT up.source_table,
                            up.id,
                            up.faculty_email,
                            up.title,
                            up.amount,
                            up.academic_year,
                            up.role,
                            up.project_status,
                            up.project_key,
                            row_number() OVER (PARTITION BY up.project_key ORDER BY
                                CASE
                                    WHEN ((lower(COALESCE(up.role, ''::text)) ~~ '%principal%'::text) OR (lower(COALESCE(up.role, ''::text)) = 'pi'::text)) THEN 1
                                    ELSE 2
                                END, up.id) AS rn
                           FROM (( SELECT 'research_projects'::text AS source_table,
                                    research_projects.id,
                                    research_projects.faculty_email,
                                    research_projects.title,
                                    research_projects.amount,
                                    research_projects.academic_year,
                                    research_projects.role,
                                    research_projects.project_status,
                                    md5(((((lower(TRIM(BOTH FROM research_projects.title)) || '|'::text) || COALESCE((research_projects.amount)::text, '0'::text)) || '|'::text) || lower(TRIM(BOTH FROM COALESCE(research_projects.agency, ''::text))))) AS project_key
                                   FROM public.research_projects
                                  WHERE ((NULLIF(TRIM(BOTH FROM research_projects.title), ''::text) IS NOT NULL) AND ((COALESCE(TRIM(BOTH FROM research_projects.project_status), ''::text) = ''::text) OR (lower(COALESCE(research_projects.project_status, ''::text)) ~ similar_to_escape('%(sanction|ongoing|complete|closed|approved|active|grant)%'::text))) AND (lower(COALESCE(research_projects.project_status, ''::text)) <> ALL (ARRAY['proposed'::text, 'submitted'::text, 'rejected'::text, 'unknown'::text, 'draft'::text])))
                                UNION ALL
                                 SELECT 'external_research_projects'::text AS source_table,
                                    external_research_projects.id,
                                    external_research_projects.faculty_email,
                                    external_research_projects.title,
                                    external_research_projects.amount,
                                    external_research_projects.academic_year,
                                    ''::text AS role,
                                    external_research_projects.project_status,
                                    md5(((((lower(TRIM(BOTH FROM external_research_projects.title)) || '|'::text) || COALESCE((external_research_projects.amount)::text, '0'::text)) || '|'::text) || lower(TRIM(BOTH FROM COALESCE(external_research_projects.agency, ''::text))))) AS project_key
                                   FROM public.external_research_projects
                                  WHERE ((NULLIF(TRIM(BOTH FROM external_research_projects.title), ''::text) IS NOT NULL) AND ((COALESCE(TRIM(BOTH FROM external_research_projects.project_status), ''::text) = ''::text) OR (lower(COALESCE(external_research_projects.project_status, ''::text)) ~ similar_to_escape('%(sanction|ongoing|complete|closed|approved|active|grant)%'::text))) AND (lower(COALESCE(external_research_projects.project_status, ''::text)) <> ALL (ARRAY['proposed'::text, 'submitted'::text, 'rejected'::text, 'unknown'::text, 'draft'::text])))) up
                             JOIN public.faculty_profiles fp ON ((lower(TRIM(BOTH FROM fp.email)) = lower(TRIM(BOTH FROM up.faculty_email)))))
                          WHERE (fp.is_active = true)) x
                  WHERE (x.rn = 1)) deduped_projects
        )
 SELECT academic_year,
    count(
        CASE
            WHEN (type = 'pub'::text) THEN 1
            ELSE NULL::integer
        END) AS publications,
    count(
        CASE
            WHEN (type = 'book'::text) THEN 1
            ELSE NULL::integer
        END) AS books,
    count(
        CASE
            WHEN (type = 'patent'::text) THEN 1
            ELSE NULL::integer
        END) AS patents,
    count(
        CASE
            WHEN (type = 'proj'::text) THEN 1
            ELSE NULL::integer
        END) AS projects,
    sum(
        CASE
            WHEN (type = 'proj'::text) THEN amount
            ELSE (0)::numeric
        END) AS funding
   FROM year_union
  WHERE (NULLIF(TRIM(BOTH FROM academic_year), ''::text) IS NOT NULL)
  GROUP BY academic_year
  ORDER BY academic_year
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_research_yearly_trend OWNER TO postgres;

--
-- Name: non_teaching_appraisals; Type: TABLE; Schema: public; Owner: fac_user
--

CREATE TABLE public.non_teaching_appraisals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    staff_email text NOT NULL,
    academic_year text NOT NULL,
    payload jsonb NOT NULL,
    status text DEFAULT 'Draft'::text NOT NULL,
    self_total numeric DEFAULT 0 NOT NULL,
    ro_total numeric DEFAULT 0 NOT NULL,
    registrar_total numeric DEFAULT 0 NOT NULL,
    vc_total numeric DEFAULT 0 NOT NULL,
    submitted_at timestamp with time zone,
    ro_reviewed_at timestamp with time zone,
    registrar_reviewed_at timestamp with time zone,
    vc_reviewed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT non_teaching_appraisals_status_check CHECK ((status = ANY (ARRAY['Draft'::text, 'Submitted'::text, 'Pending RO Review'::text, 'Pending Registrar Review'::text, 'Reporting Officer Reviewed'::text, 'Registrar Reviewed'::text, 'VC Approved'::text])))
);


ALTER TABLE public.non_teaching_appraisals OWNER TO fac_user;

--
-- Name: non_teaching_part_a_items; Type: TABLE; Schema: public; Owner: fac_user
--

CREATE TABLE public.non_teaching_part_a_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    staff_email text NOT NULL,
    academic_year text NOT NULL,
    item_key text NOT NULL,
    title text NOT NULL,
    max_marks numeric NOT NULL,
    details text,
    self_marks numeric,
    ro_marks numeric,
    registrar_marks numeric,
    vc_marks numeric,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.non_teaching_part_a_items OWNER TO fac_user;

--
-- Name: non_teaching_part_b_ratings; Type: TABLE; Schema: public; Owner: fac_user
